function system_availability_value = system_availability_CS6(A) % large-scale system with 15 subsystems
    % A subsystems availability
    U = 1 - A;
    system_availability_value = A(1)*A(2)*A(3)*A(4)*A(5)*A(6) + A(9)*A(10)*A(11)*A(12)*A(13)*A(14)*A(15)*(U(1)+A(1)*U(2)+A(1)*A(2)*U(3)+A(1)*A(2)*A(3)*U(4)+A(1)*A(2)*A(3)*A(4)*U(5)+A(1)*A(2)*A(3)*A(4)*A(5)*U(6))+...
        A(3)*A(4)*A(5)*A(6)*A(7)*A(9)*A(10)*(U(11)+A(11)*U(12)+A(11)*A(12)*U(13)+A(11)*A(12)*A(13)*U(14)+A(11)*A(12)*A(13)*A(14)*U(15))*(U(1)+A(1)*U(2))+...
        ((U(1)+A(1)*U(2))*(U(3)+A(3)*U(4)+A(3)*A(4)*U(7))+A(1)*A(2)*U(7)*(U(3)*A(3)*U(4)))*(U(13)+A(13)*U(14)+A(13)*A(14)*U(15))*A(5)*A(6)*A(8)*A(9)*A(10)*A(11)*A(12)+...
        A(1)*A(2)*A(5)*A(6)*A(7)*A(8)*A(11)*A(12)*(A(9)*A(10)+U(9)+A(9)*U(10))*(U(3)+A(3)*U(4))*(U(13)+A(13)*U(14)+A(13)*A(14)*U(15))+...
        (U(5)+A(5)*U(6))*((U(7)+A(7)*U(11)+A(7)*A(11)*U(12))*(U(9)+A(9)*U(10))+A(9)*A(10)*(U(11)+A(11)*U(12)))*A(1)*A(2)*A(3)*A(4)*A(8)*A(13)*A(14)*A(15)+...
        A(1)*A(2)*A(7)*A(11)*A(12)*A(13)*A(14)*A(15)*(U(9)+A(9)*U(10))*(U(3)+A(3)*U(4)+A(3)*A(4)*U(5)+A(3)*A(4)*A(5)*U(6))+...
        A(3)*A(4)*A(7)*A(8)*A(9)*A(10)*A(13)*A(14)*A(15)*(U(1)+A(1)*U(2))*(U(11)+A(11)*U(12))*(U(5)+A(5)*U(6));
end